func wait(ctx context.Context) error {
	select {
	case <-ctx.Done(): // closed on cancel or timeout
		return ctx.Err() // Canceled or DeadlineExceeded
	case <-time.After(time.Second):
		return nil
	}
}
// ctx.Err() is nil until Done() closes.

func main() {
	root := context.Background()
	// child inherits from root and adds a 2s deadline
	ctx, cancel := context.WithTimeout(root, 2*time.Second)
	defer cancel()
	deadline, _ := ctx.Deadline()
	fmt.Println("deadline set:", deadline.After(time.Now()))
	// Output: deadline set: true
}

func fetch(parent context.Context) error {
	ctx, cancel := context.WithTimeout(parent, time.Second)
	defer cancel() // releases the timer even on early return
	return callDownstream(ctx)
}

func callDownstream(ctx context.Context) error {
	<-ctx.Done()
	return ctx.Err()
}

func worker(ctx context.Context, jobs <-chan int) error {
	for {
		select {
		case <-ctx.Done(): // stop promptly when signalled
			return ctx.Err()
		case j := <-jobs:
			fmt.Println("processing", j)
		}
	}
}

