type Server struct{ db *sql.DB }

// ctx first: the deadline flows into the query and aborts it on timeout.
func (s *Server) Handle(ctx context.Context, id int) error {
	_, err := s.db.ExecContext(ctx, "UPDATE t SET seen=now() WHERE id=$1", id)
	return err
}

