	ticker := time.NewTicker(40 * time.Millisecond)
	defer ticker.Stop()
	for {
		select {
		case <-ctx.Done(): // cancelled or timed out
			return ctx.Err()
		case <-ticker.C:
			fmt.Println("tick")
		}
	}
}

