package main

import (
	"context"
	"fmt"
	"time"
)

func fetch(ctx context.Context) (string, error) {
	select {
	case <-ctx.Done(): // caller's deadline fired first
		return "", ctx.Err()
	case <-time.After(200 * time.Millisecond): // the work finishing
		return "data", nil
	}
}

func main() {
	ctx, cancel := context.WithTimeout(context.Background(), 50*time.Millisecond)
	defer cancel()
	_, err := fetch(ctx)
	fmt.Println(err) // context deadline exceeded
}

