package solution

import (
	"context"
	"errors"
	"testing"
	"time"
)

func TestFirstSuccess(t *testing.T) {
	fns := []func(context.Context) (int, error){
		func(ctx context.Context) (int, error) {
			time.Sleep(50 * time.Millisecond)
			return 1, nil
		},
		func(ctx context.Context) (int, error) {
			return 2, nil // fastest success
		},
	}
	got, err := First(context.Background(), fns)
	if err != nil || got != 2 {
		t.Fatalf("got (%d,%v) want (2,nil)", got, err)
	}
}

func TestFirstTimeout(t *testing.T) {
	fns := []func(context.Context) (int, error){
		func(ctx context.Context) (int, error) {
			return 0, errors.New("boom") // never succeeds
		},
	}
	ctx, cancel := context.WithTimeout(context.Background(), 20*time.Millisecond)
	defer cancel()
	if _, err := First(ctx, fns); !errors.Is(err, context.DeadlineExceeded) {
		t.Fatalf("want DeadlineExceeded, got %v", err)
	}
}

