func search(ctx context.Context) int {
	out := make(chan int, 1) // buffered: the send always succeeds
	go func() {
		out <- slowQuery() // never blocks now, so the goroutine exits
	}()
	select {
	case v := <-out:
		return v
	case <-ctx.Done():
		return -1 // goroutine still finishes and the buffered send completes
	}
}

import "context"

type result[T any] struct {
	val T
	err error
}

// WithTimeoutResult runs fn(ctx) and returns its result, or ctx.Err() if the
// context finishes first. The goroutine never leaks: it sends on a buffered
// channel that always accepts the one value.
func WithTimeoutResult[T any](ctx context.Context, fn func(context.Context) (T, error)) (T, error) {
	ch := make(chan result[T], 1) // cap 1: send never blocks
	go func() {
		v, err := fn(ctx)
		ch <- result[T]{v, err} // succeeds even if no one is receiving
	}()
	select {
	case r := <-ch:
		return r.val, r.err
	case <-ctx.Done():
		var zero T
		return zero, ctx.Err()
	}
}

import (
	"context"
	"time"
)

// DoWithRetry retries fn up to attempts times, aborting on ctx cancellation.
func DoWithRetry(ctx context.Context, attempts int, fn func() error) error {
	var err error
	for i := 0; i < attempts; i++ {
		if err = fn(); err == nil {
			return nil // success
		}
		if i == attempts-1 {
			break // last attempt failed; don't wait
		}
		select {
		case <-ctx.Done(): // cancellation beats the backoff
			return ctx.Err()
		case <-time.After(100 * time.Millisecond): // backoff before retry
		}
	}
	return err // last error after exhausting attempts
}
